#!/usr/bin/env python3
"""Writes src/settings.rs: the 152 settings of Rind FM (a DX7 voice's 145 values, six operator switches, the output)."""
OP = [  # (id, name, lo, hi, start, magnet)
    ("r1", "EG Rate 1", 0, 99, 99, None), ("r2", "EG Rate 2", 0, 99, 99, None),
    ("r3", "EG Rate 3", 0, 99, 99, None), ("r4", "EG Rate 4", 0, 99, 99, None),
    ("l1", "EG Level 1", 0, 99, 99, None), ("l2", "EG Level 2", 0, 99, 99, None),
    ("l3", "EG Level 3", 0, 99, 99, None), ("l4", "EG Level 4", 0, 99, 0, None),
    ("bp", "Break Point", 0, 99, 39, None), ("ld", "Scale Left Depth", 0, 99, 0, None),
    ("rd", "Scale Right Depth", 0, 99, 0, None), ("lc", "Scale Left Curve", 0, 3, 0, None),
    ("rc", "Scale Right Curve", 0, 3, 0, None), ("rs", "Rate Scaling", 0, 7, 0, None),
    ("ams", "A Mod Sens", 0, 3, 0, None), ("kvs", "Key Velocity", 0, 7, 0, None),
    ("lvl", "Output Level", 0, 99, 0, None), ("mode", "Freq Mode", 0, 1, 0, None),
    ("coarse", "Freq Coarse", 0, 31, 1, None), ("fine", "Freq Fine", 0, 99, 0, None),
    ("det", "Detune", 0, 14, 7, 7),
]
GLOBAL = [
    ("peg_r1", "Pitch EG Rate 1", 0, 99, 99, None), ("peg_r2", "Pitch EG Rate 2", 0, 99, 99, None),
    ("peg_r3", "Pitch EG Rate 3", 0, 99, 99, None), ("peg_r4", "Pitch EG Rate 4", 0, 99, 99, None),
    ("peg_l1", "Pitch EG Level 1", 0, 99, 50, 50), ("peg_l2", "Pitch EG Level 2", 0, 99, 50, 50),
    ("peg_l3", "Pitch EG Level 3", 0, 99, 50, 50), ("peg_l4", "Pitch EG Level 4", 0, 99, 50, 50),
    ("algorithm", "Algorithm", 0, 31, 0, None), ("feedback", "Feedback", 0, 7, 0, None),
    ("osc_sync", "Oscillator Key Sync", 0, 1, 1, None), ("lfo_speed", "LFO Speed", 0, 99, 35, None),
    ("lfo_delay", "LFO Delay", 0, 99, 0, None), ("lfo_pmd", "LFO Pitch Mod Depth", 0, 99, 0, None),
    ("lfo_amd", "LFO Amp Mod Depth", 0, 99, 0, None), ("lfo_sync", "LFO Key Sync", 0, 1, 1, None),
    ("lfo_wave", "LFO Wave", 0, 5, 0, None), ("pitch_mod_sens", "Pitch Mod Sens", 0, 7, 3, None),
    ("transpose", "Transpose", 0, 48, 24, 24),
]
rows = []
# Operators in the order a voice stores them: operator 6 first.
for n in range(6, 0, -1):
    for (i, name, lo, hi, st, mg) in OP:
        start = 99 if (i == "lvl" and n == 1) else st
        rows.append((f"op{n}_{i}", f"Op {n} {name}", lo, hi, start, mg))
rows += GLOBAL
assert len(rows) == 145, len(rows)
for n in range(1, 7):
    rows.append((f"op{n}_on", f"Op {n} Switch", 0, 1, 1, None))
rows.append(("output", "Output", -240, 120, 0, 0))
out = ["// Generated by gen.py: Rind FM's settings, in a voice's order (setting k = byte k of a DX7 voice as the engine plays it).",
       "use ml_small_fx::Setting;", "", f"pub const COUNT: usize = {len(rows)};", "",
       f"pub static SETTINGS: [Setting; {len(rows)}] = ["]
for (i, name, lo, hi, st, mg) in rows:
    m = f"Some({mg})" if mg is not None else "None"
    out.append(f'    Setting {{ id: "{i}", name: "{name}", range: ({lo}, {hi}), start: {st}, magnet: {m} }},')
out.append("];")
out.append("")
out.append(f"pub static IDS: [&str; {len(rows)}] = [")
out += [f'    "{r[0]}",' for r in rows]
out.append("];")
open("src/settings.rs", "w").write("\n".join(out) + "\n")
print(len(rows))
